import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [dark, setDark] = useState(false);
  // энд бичнэ үү: dark-аас хамааруулж дэвсгэр/үсгийн өнгө сонго
  const bg = "#ffffff";
  const fg = "#18181b";
  return (
    <View nativeID="screen" style={[styles.s, { backgroundColor: bg }]}>
      <Text style={[styles.h, { color: fg }]}>Shop.mn</Text>
      <Pressable nativeID="toggle" style={styles.b} onPress={() => setDark((d) => !d)}><Text style={styles.t}>Горим солих</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 20, alignItems: "center", justifyContent: "center" },
  h: { fontSize: 28, fontWeight: "bold" },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12 }, t: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);

import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [dark, setDark] = useState(false);
  const bg = dark ? "#0f172a" : "#ffffff";
  const fg = dark ? "#f8fafc" : "#18181b";
  return (
    <View nativeID="screen" style={[styles.s, { backgroundColor: bg }]}>
      <Text style={[styles.h, { color: fg }]}>Shop.mn</Text>
      <Pressable nativeID="toggle" style={styles.b} onPress={() => setDark((d) => !d)}><Text style={styles.t}>Горим солих</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 20, alignItems: "center", justifyContent: "center" },
  h: { fontSize: 28, fontWeight: "bold" },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12 }, t: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);
